27	// corruptRefundResult 像调用者为自己展示所做的那样，破坏性改写一份退款结果：
28	// 顶层状态、说明、去向、金额与完整记录的全部字段一律换成伪造值。
29	func corruptRefundResult(r *RefundResult) {
30		r.ID = "HACK-ID"
31		r.Status = "forged-status"
32		r.Reason = "forged reason"
33		r.SettlementID = "p-fake"
