41		r.Record.SettlementID = "p-fake"
42		r.Record.Reason = "forged reason"
43		r.Record.Account = "zz"
44		r.Record.Asset = "btc"
45		r.Record.Amount = 1
46		r.Record.Fee = 1
47		r.Record.Charged = 2
48		r.Record.AfterSeq = 99
