52	// assertRefundResultRecord 断言一份退款结果（成功或重复）携带的详情逐字段等于
53	// 预期：顶层原付款编号、账户、资产、退款总额、原因，以及完整退款记录。
54	func assertRefundResultRecord(t *testing.T, got RefundResult, wantStatus string, want RefundRecord) {
55		t.Helper()
56		if got.Status != wantStatus {
57			t.Fatalf("status=%s want %s: %+v", got.Status, wantStatus, got)
58		}
59		if got.ID != want.ID {
60			t.Fatalf("id=%q want %q: %+v", got.ID, want.ID, got)
61		}
62		if got.Reason != want.Reason || got.SettlementID != want.SettlementID ||
63			got.Account != want.Account || got.Asset != want.Asset || got.Charged != want.Charged {
64			t.Fatalf("top-level detail:\n got %+v\nwant id=%s reason=%s sid=%s %s/%s charged=%d",
65				got, want.ID, want.Reason, want.SettlementID, want.Account, want.Asset, want.Charged)
66		}
67		if got.Record == nil {
68			t.Fatalf("%s result must carry a record: %+v", wantStatus, got)
69		}
70		if *got.Record != want {
71			t.Fatalf("record:\n got %+v\nwant %+v", *got.Record, want)
72		}
73	}
