192			ID: "r1", SettlementID: "p1", Reason: "reason A",
193			Account: "aa", Asset: "usdc", Amount: 100, Fee: 0, Charged: 100,
194			AfterSeq: 2, Seq: 1,
195		}
196		assertRefundResultRecord(t, first, StatusRefundSuccess, wantR1)
197		balAfter, _ := l.Balance("aa", "usdc") // 1_000_000-200+100 = 999_900
198	
199		// 原退款请求原样再次提交：duplicate，携带最初成功时的详情。
200		dup := mustRefundOne(t, l, "r1", "p1", "reason A")
201		assertRefundResultRecord(t, dup, StatusDuplicate, wantR1)
202		if bal, _ := l.Balance("aa", "usdc"); bal != balAfter {
203			t.Fatalf("duplicate changed balance: %d vs %d", bal, balAfter)
204		}
205	
206		// 调用者改写自己留存的成功结果（编号、原因、目标、去向、金额全部伪造）。
207		corruptRefundResult(&first)
208		// 改写也波及不到刚取得的 duplicate 结果。
209		assertRefundResultRecord(t, dup, StatusDuplicate, wantR1)
210	
211		// 原请求再次提交，返回的仍是最初成功的详情，而不是调用者改写后的内容。
212		dup2 := mustRefundOne(t, l, "r1", "p1", "reason A")
213		assertRefundResultRecord(t, dup2, StatusDuplicate, wantR1)
214	
215		// 提交“已修改的请求”继续按既有规则处理：
216		// 用原退款编号换成另一个合法原因 => conflict。
217		if r := mustRefundOne(t, l, "r1", "p1", "reason B"); r.Status != StatusConflict {
