229		// 以上均不新增退款记录、不重复增加余额。
230		snap := mustQuery(t, l)
231		if len(snap.Refunds) != 1 || snap.Refunds[0] != wantR1 {
232			t.Fatalf("ledger refunds:\n got %+v\nwant only %+v", snap.Refunds, wantR1)
233		}
