239	// TestRefundSameBatchSuccessAndDuplicateResultsAreIndependent 锁定同一批次内
240	// 连续出现相同退款请求时的结果隔离：首次成功项与后续重复项各自持有可修改的
241	// 记录副本，改动其中一项不波及其他项，也不波及此前批次保留的结果或账本事实。
242	func TestRefundSameBatchSuccessAndDuplicateResultsAreIndependent(t *testing.T) {
243		path := newTestLedger(t, []BalanceInit{
244			{Account: "aa", Asset: "usdc", Balance: 2000},
245			{Account: "bb", Asset: "usdc", Balance: 500},
246		})
247		l := openOrFail(t, path)
248	
249		// 三笔付款：p0、p1 在 aa（100、1000@100bps=>charged1010），p2 在 bb（200）。
250		if r := mustSettle(t, l, 0, intent("p0", "aa", "usdc", 100)); r.Status != StatusSettled {
251			t.Fatalf("settle p0: %+v", r)
252		}
253		if r := mustSettle(t, l, 100, intent("p1", "aa", "usdc", 1000)); r.Status != StatusSettled {
254			t.Fatalf("settle p1: %+v", r)
255		}
256		if r := mustSettle(t, l, 0, intent("p2", "bb", "usdc", 200)); r.Status != StatusSettled {
257			t.Fatalf("settle p2: %+v", r)
258		}
259	
260		// 此前批次先成功一笔并留存结果（三笔付款都已结算，r0 退回后 aa 余 990）。
261		saved0 := mustRefundOne(t, l, "r0", "p0", "earlier batch")
262		wantR0 := RefundRecord{
263			ID: "r0", SettlementID: "p0", Reason: "earlier batch",
264			Account: "aa", Asset: "usdc", Amount: 100, Fee: 0, Charged: 100,
265			AfterSeq: 3, Seq: 1,
266		}
267		assertRefundResultRecord(t, saved0, StatusRefundSuccess, wantR0)
268	
269		// 同一批次内连续提交相同退款请求：每项首次成功、紧随的重复申请。
270		rb, err := l.Refund(RefundBatch{Refunds: []RefundRequest{
271			refundReq("r1", "p1", "same batch"), // 成功：aa 990+1010=2000
272			refundReq("r1", "p1", "same batch"), // 同批次重复
273			refundReq("r2", "p2", "same batch"), // 成功：bb 300+200=500
274			refundReq("r2", "p2", "same batch"), // 同批次重复
275		}})
276		if err != nil {
277			t.Fatal(err)
278		}
279		wantStatus := []string{
280			StatusRefundSuccess, StatusDuplicate, StatusRefundSuccess, StatusDuplicate,
281		}
282		if got := refundStatuses(rb); !reflect.DeepEqual(got, wantStatus) {
283			t.Fatalf("statuses=%v want %v", got, wantStatus)
284		}
285		wantR1 := RefundRecord{
286			ID: "r1", SettlementID: "p1", Reason: "same batch",
287			Account: "aa", Asset: "usdc", Amount: 1000, Fee: 10, Charged: 1010,
288			AfterSeq: 3, Seq: 2,
289		}
290		wantR2 := RefundRecord{
291			ID: "r2", SettlementID: "p2", Reason: "same batch",
292			Account: "bb", Asset: "usdc", Amount: 200, Fee: 0, Charged: 200,
293			AfterSeq: 3, Seq: 3,
294		}
295		wants := []RefundRecord{wantR1, wantR1, wantR2, wantR2}
296		for i, want := range wants {
297			assertRefundResultRecord(t, rb.Results[i], wantStatus[i], want)
298		}
299	
300		// 四个结果（含成功项与重复项的 Record）必须是各自独立的分配，两两不共享。
301		for i := 0; i < len(rb.Results); i++ {
302			for j := i + 1; j < len(rb.Results); j++ {
303				if rb.Results[i].Record == rb.Results[j].Record {
304					t.Fatalf("results %d and %d share the same *RefundRecord", i, j)
305				}
306			}
307		}
308	
309		// 逐项直接破坏性改写手里的结果：每改一项，其余尚未被改的项与此前批次保留
310		// 的结果都必须保持原值，证明成功项与重复项各自持有独立副本，改动一项
311		// （含其 Record 指向的完整记录）不会回波到同批次其他结果或更早保留的结果。
312		corrupted := map[int]bool{}
313		for i := range rb.Results {
314			corruptRefundResult(&rb.Results[i])
315			corrupted[i] = true
316			for j, want := range wants {
317				if corrupted[j] {
318					continue // 已被自己那次改写，不要求保持原值
319				}
320				if *rb.Results[j].Record != want {
321					t.Fatalf("after corrupting result %d, result %d changed:\n got %+v\nwant %+v",
322						i, j, *rb.Results[j].Record, want)
323				}
324				if rb.Results[j].Status != wantStatus[j] {
325					t.Fatalf("after corrupting result %d, result %d status=%s want %s",
326						i, j, rb.Results[j].Status, wantStatus[j])
327				}
328			}
329			if *saved0.Record != wantR0 {
330				t.Fatalf("after corrupting result %d, earlier held result changed: %+v",
331					i, *saved0.Record)
332			}
333		}
334	
335		// 账本事实不受任何结果改写影响：三条退款记录原值，余额只按真实退款变动。
336		snap := mustQuery(t, l)
337		if !reflect.DeepEqual(snap.Refunds, []RefundRecord{wantR0, wantR1, wantR2}) {
338			t.Fatalf("ledger refunds after result edits: %+v", snap.Refunds)
339		}
340		if bal, _ := l.Balance("aa", "usdc"); bal != 2000 {
341			t.Fatalf("aa/usdc=%d want 2000", bal)
342		}
343		if bal, _ := l.Balance("bb", "usdc"); bal != 500 {
344			t.Fatalf("bb/usdc=%d want 500", bal)
345		}
346		// 原请求重提仍 duplicate 且详情来自账本，而非任何被改写的结果。
347		dup := mustRefundOne(t, l, "r1", "p1", "same batch")
348		assertRefundResultRecord(t, dup, StatusDuplicate, wantR1)
349	}
350	
351	// TestRefundResultsAcrossPaymentsAndLaterRefunds 锁定不同付款的成功退款结果
352	// 互不影响，且后续新增退款不能改变旧结果的编号、成功序号与金额。
353	func TestRefundResultsAcrossPaymentsAndLaterRefunds(t *testing.T) {
354		path := newTestLedger(t, []BalanceInit{
355			{Account: "aa", Asset: "usdc", Balance: 2000},
356			{Account: "bb", Asset: "usdc", Balance: 500},
357		})
358		l := openOrFail(t, path)
359	
360		// p1 含手续费（charged 1010，aa），p2 无手续费（charged 200，bb）。
361		if r := mustSettle(t, l, 100, intent("p1", "aa", "usdc", 1000)); r.Status != StatusSettled {
362			t.Fatalf("settle p1: %+v", r)
363		}
364		if r := mustSettle(t, l, 0, intent("p2", "bb", "usdc", 200)); r.Status != StatusSettled {
365			t.Fatalf("settle p2: %+v", r)
366		}
367		old1 := mustRefundOne(t, l, "r1", "p1", "cancel p1")
368		old2 := mustRefundOne(t, l, "r2", "p2", "cancel p2")
369		wantR1 := RefundRecord{
370			ID: "r1", SettlementID: "p1", Reason: "cancel p1",
371			Account: "aa", Asset: "usdc", Amount: 1000, Fee: 10, Charged: 1010,
372			AfterSeq: 2, Seq: 1,
373		}
374		wantR2 := RefundRecord{
375			ID: "r2", SettlementID: "p2", Reason: "cancel p2",
376			Account: "bb", Asset: "usdc", Amount: 200, Fee: 0, Charged: 200,
377			AfterSeq: 2, Seq: 2,
378		}
379		assertRefundResultRecord(t, old1, StatusRefundSuccess, wantR1)
380		assertRefundResultRecord(t, old2, StatusRefundSuccess, wantR2)
381		if old1.Record == old2.Record {
382			t.Fatal("success results of different payments share one record allocation")
383		}
384	
385		// 改写第二笔付款的结果：第一笔结果（此前保留）与账本中的 r2 都不受影响。
386		corruptRefundResult(&old2)
387		if *old1.Record != wantR1 || old1.Status != StatusRefundSuccess || old1.Charged != 1010 {
388			t.Fatalf("older result changed after editing a different payment's result: %+v", old1)
389		}
390		if rf := mustQuery(t, l).Refunds; len(rf) != 2 || rf[1] != wantR2 {
391			t.Fatalf("real r2 altered via another held result: %+v", rf)
392		}
393	
394		// 后续新增一笔付款并成功退款：新退款序号续增，旧结果编号、序号、金额不变。
395		if r := mustSettle(t, l, 0, intent("p3", "aa", "usdc", 50)); r.Status != StatusSettled {
396			t.Fatalf("settle p3: %+v", r) // aa 2000-50=1950
397		}
398		new3 := mustRefundOne(t, l, "r3", "p3", "cancel p3") // aa 1950+50=2000
399		wantR3 := RefundRecord{
400			ID: "r3", SettlementID: "p3", Reason: "cancel p3",
401			Account: "aa", Asset: "usdc", Amount: 50, Fee: 0, Charged: 50,
402			AfterSeq: 3, Seq: 3,
403		}
404		assertRefundResultRecord(t, new3, StatusRefundSuccess, wantR3)
405	
406		// 旧结果（含已被改写的 old2 之外的 old1）编号、成功序号、金额保持首次成功时的值。
407		if old1.ID != "r1" || old1.Record.ID != "r1" || old1.Record.Seq != 1 ||
408			old1.Record.Charged != 1010 || old1.Record.Amount != 1000 || old1.Record.Fee != 10 {
409			t.Fatalf("old r1 result changed after a later refund: %+v", old1)
410		}
411		if old1.SettlementID != "p1" || old1.Account != "aa" || old1.Asset != "usdc" {
412			t.Fatalf("old r1 destination changed: %+v", old1)
413		}
414	
415		// 改写新结果同样不能回波到旧结果或账本。
416		corruptRefundResult(&new3)
417		if *old1.Record != wantR1 {
418			t.Fatalf("old r1 changed after editing the newest result: %+v", *old1.Record)
419		}
420	
421		// 账本视角：三笔退款按成功先后排列，序号与金额稳定；旧请求重提仍 duplicate
422		// 并携带最初详情（seq=1），不因新退款或任何结果改写而变化。
423		snap := mustQuery(t, l)
424		if !reflect.DeepEqual(snap.Refunds, []RefundRecord{wantR1, wantR2, wantR3}) {
425			t.Fatalf("ledger refunds:\n got %+v\nwant %+v / %+v / %+v", snap.Refunds, wantR1, wantR2, wantR3)
426		}
427		if len(snap.Settlements) != 3 {
428			t.Fatalf("settlements=%d want 3", len(snap.Settlements))
429		}
430		dup1 := mustRefundOne(t, l, "r1", "p1", "cancel p1")
431		assertRefundResultRecord(t, dup1, StatusDuplicate, wantR1)
432		dup2 := mustRefundOne(t, l, "r2", "p2", "cancel p2")
433		assertRefundResultRecord(t, dup2, StatusDuplicate, wantR2)
434	
435		// 余额：aa 只经历 p1/r1（相抵）与 p3/r3（相抵）=>2000；bb p2/r2 相抵 =>500。
436		if bal, _ := l.Balance("aa", "usdc"); bal != 2000 {
437			t.Fatalf("aa/usdc=%d want 2000", bal)
438		}
439		if bal, _ := l.Balance("bb", "usdc"); bal != 500 {
440			t.Fatalf("bb/usdc=%d want 500", bal)
441		}
442	}
443

