11	// 本文件为离线对账报告（ReconcileFlow / ReconcileFlowRanged 返回的 *ReconReport）
12	// 与真实账本之间的独立性提供回归保障。Go 调用者拿到全量或按成功序号限定范围的
13	// 报告后，可能修改其中的记录详情、差异说明和重复位置供自己继续处理；本文件锁定：
14	//
15	//  1. 结果之间彼此独立：同一付款/退款编号在输入中多次出现时，范围内重复组逐项
16	//     返回，整组各项都携带完整输入位置及对应成功记录的独立副本；调用者改动其中
17	//     一项的编号、账户、金额、付款与退款关联或位置列表，其他项保留原内容。
18	//     付款编号与退款编号各自独立，同名编号编辑一类结果不能影响另一类。
19	//  2. 范围外优先且彼此独立：记录在范围外时继续优先报告 out_of_scope 并保留关联
20	//     信息；同一范围外记录被多条流水引用时，编辑其中一条结果不连带改变其他条目。
21	//  3. 报告与账本空间独立：调用者改动逐项详情、字段差异、缺失记录和金额汇总后，
22	//     查询到的余额与成功历史保持原样；用原流水与原范围重新对账，仍得到依据真实
23	//     账本计算的状态、关联、位置及汇总，不沿用调用者改过的数据。
24	//  4. 只读：对账与编辑返回值都不改写账本文件，已有付款、退款行为不受影响。
25	//  5. 时效独立：取得报告后账本再发生付款或退款，新报告反映真实变化，旧报告仍保留
26	//     取得时的记录、缺失列表、金额汇总、最大成功序号与实际范围；原先未退款的付款
27	//     后来退款时，旧报告付款不得自动出现新退款关联，新报告必须带上该关联，即使
28	//     关联退款不在选定范围内。空流水正常返回的缺失报告遵守同样的独立性。
29	//
30	// 核对规则、报告格式与 ReconcileFlow/ReconcileFlowRanged 公开入口均不在本文件变更。
31	
32	// reconBounds 是构造核对范围的便捷函数：after < seq <= through。
33	func reconBounds(pa, pt, ra, rt int64) ReconcileBounds {
34		return ReconcileBounds{
35			PaymentAfter: &pa, PaymentThrough: &pt,
36			RefundAfter: &ra, RefundThrough: &rt,
37		}
38	}
39	
40	// mustReconcile 执行一次对账，失败即终止用例。
41	func mustReconcile(t *testing.T, l *Ledger, entries []FlowEntry, bounds ReconcileBounds) *ReconReport {
42		t.Helper()
43		rep, err := l.ReconcileFlowRanged(entries, bounds)
44		if err != nil {
45			t.Fatalf("ReconcileFlowRanged: %v", err)
46		}
47		return rep
48	}
49	
50	// cloneReconReport 深拷贝一份对账报告，作为“调用者取得时”的冻结基线：
51	// ReconRecordRef 是指针字段，逐项结果必须连同其 *Record 一起复制，否则后续比较
52	// 会被调用者对自己那份报告的编辑污染。
53	func cloneReconReport(r *ReconReport) *ReconReport {
54		b, err := json.Marshal(r)
55		if err != nil {
56			panic(err)
57		}
58		var cp ReconReport
59		if err := json.Unmarshal(b, &cp); err != nil {
60			panic(err)
61		}
62		return &cp
63	}
64	
65	// corruptReconResult 像调用者为自己继续处理所做的那样，破坏性改写一条逐项结果：
66	// 顶层编号/状态/位置列表、差异说明，以及命中记录的编号、账户、资产、金额、
67	// 手续费、扣款总额、序号、原付款编号与退款关联一律换成伪造值。
68	func corruptReconResult(r *ReconResult) {
69		r.ID = "HACK-ID"
70		r.Kind = "forged-kind"
71		r.Status = "forged-status"
72		if r.Positions != nil {
73			r.Positions[0] = 4242
74			r.Positions = append(r.Positions, 999)
75		} else {
76			r.Positions = []int{7, 7}
77		}
78		if r.Diffs != nil {
79			r.Diffs[0] = FieldDiff{Field: "forged", Ledger: "HACK-L", Flow: "HACK-F"}
80		} else {
81			r.Diffs = []FieldDiff{{Field: "injected", Ledger: "x", Flow: "y"}}
82		}
83		if r.Record == nil {
84			return
85		}
86		r.Record.Kind = "forged-kind"
87		r.Record.ID = "HACK-REC"
88		r.Record.Account = "zz"
89		r.Record.Asset = "btc"
90		r.Record.Amount = 1
91		r.Record.Fee = 1
92		r.Record.Charged = 2
93		r.Record.Seq = 77
94		r.Record.SettlementID = "p-fake"
95		r.Record.RefundID = "r-fake"
96		r.Record.RefundSeq = 88
97	}
98	
99	// corruptReconRef 破坏性改写一条缺失/汇总中携带的记录引用（全部字段，含两类关联）。
100	func corruptReconRef(r *ReconRecordRef) {
101		r.Kind = "forged-kind"
102		r.ID = "HACK-MISSING"
103		r.Account = "zz"
104		r.Asset = "btc"
105		r.Amount = 11
106		r.Fee = 22
107		r.Charged = 33
108		r.Seq = 66
109		r.SettlementID = "p-fake"
110		r.RefundID = "r-fake"
111		r.RefundSeq = 55
112	}
113	
114	// corruptReconTotals 破坏性改写单侧汇总的每一行（金额换成伪造的大数字符串）。
115	func corruptReconTotals(rows []ReconTotalRow) {
116		for i := range rows {
117			rows[i].Account = "zz-" + rows[i].Account
118			rows[i].ChargedTotal = "999999"
119			rows[i].RefundedTotal = "888888"
120			rows[i].NetCharged = "111111"
