124	// assertReconReportDeepEqual 逐字段断言两份报告一致（含指针记录与各汇总）。
125	func assertReconReportDeepEqual(t *testing.T, got, want *ReconReport, label string) {
126		t.Helper()
127		if !reflect.DeepEqual(got, want) {
128			gj, _ := json.Marshal(got)
129			wj, _ := json.Marshal(want)
130			t.Fatalf("%s:\n got %s\nwant %s", label, gj, wj)
131		}
132	}
