134	// assertResultUntouched 断言一条逐项结果仍与冻结基线完全一致。
135	func assertResultUntouched(t *testing.T, got, want ReconResult, label string) {
136		t.Helper()
137		if !reflect.DeepEqual(got, want) {
138			gj, _ := json.Marshal(got)
139			wj, _ := json.Marshal(want)
140			t.Fatalf("%s:\n got %s\nwant %s", label, gj, wj)
141		}
142	}
143	
144	// assertRefUntouched 断言一条记录引用逐字段保持原值（缺失列表与命中记录共用）。
145	func assertRefUntouched(t *testing.T, got, want ReconRecordRef, label string) {
146		t.Helper()
147		if got != want {
148			t.Fatalf("%s:\n got %+v\nwant %+v", label, got, want)
149		}
150	}
151	
152	// ---- 1. 范围内重复组：逐项独立副本 ----
153	
154	// TestReconcileDuplicateResultsAreIndependent 锁定同一付款编号在输入中多次出现时，
155	// 范围内重复组逐项返回：每项都携带完整输入位置 [0,1,2] 与同一条成功记录的独立
156	// 副本；调用者逐项破坏改写其中一条（编号、账户、金额、关联、位置列表），其余
157	// 尚未被改的项必须保留原来的状态、位置与记录详情。
158	func TestReconcileDuplicateResultsAreIndependent(t *testing.T) {
159		l := rangeLedger(t)
160		// 付款范围选 (0,3] 全量；p2(seq=2) 在范围内，出现三次，内容各不相同也仍是
161		// 整组重复（不判字段差异）。
162		entries := []FlowEntry{
163			flowEntry(0, "payment", "p2", "aa-1", "usdc", 2000, 6, 2006, ""),
164			flowEntry(1, "payment", "p2", "aa-1", "usdc", 999, 0, 999, ""),
165			flowEntry(2, "payment", "p2", "OTHER", "eth", 7, 7, 14, ""),
166		}
167		rep := mustReconcile(t, l, entries, reconBounds(0, 3, 0, 2))
168	
169		wantRec := ReconRecordRef{
170			Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc",
171			Amount: 2000, Fee: 6, Charged: 2006, Seq: 2,
172			RefundID: "r2", RefundSeq: 2, // 范围内重复项仍携带该付款的退款关联
173		}
174		for i, r := range rep.Results {
175			if r.Status != ReconDuplicate {
176				t.Fatalf("result %d status=%s want duplicate", i, r.Status)
177			}
178			if !reflect.DeepEqual(r.Positions, []int{0, 1, 2}) {
179				t.Fatalf("result %d positions=%v want [0 1 2]", i, r.Positions)
180			}
181			if len(r.Diffs) != 0 {
182				t.Fatalf("duplicate must carry no diffs, result %d: %+v", i, r.Diffs)
183			}
184			if r.Record == nil {
185				t.Fatalf("result %d must carry the ledger record", i)
186			}
187			assertRefUntouched(t, *r.Record, wantRec, "duplicate record")
188		}
189	
190		// 三个命中记录必须是各自独立的分配，两两不共享。
191		for i := 0; i < len(rep.Results); i++ {
192			for j := i + 1; j < len(rep.Results); j++ {
193				if rep.Results[i].Record == rep.Results[j].Record {
194					t.Fatalf("duplicate results %d and %d share one *ReconRecordRef", i, j)
195				}
196			}
197		}
198		// 位置列表也必须是每条结果各自的底层数组。
199		if &rep.Results[0].Positions[0] == &rep.Results[1].Positions[0] {
200			t.Fatal("duplicate results share the positions backing array")
201		}
202	
203		// 冻结逐项基线后逐项破坏：每改一项，其余尚未被改的项保持原状态/位置/记录。
204		saved := make([]ReconResult, len(rep.Results))
205		copy(saved, rep.Results)
206		corrupted := map[int]bool{}
207		for i := range rep.Results {
208			corruptReconResult(&rep.Results[i])
209			corrupted[i] = true
210			for j := range rep.Results {
211				if corrupted[j] {
212					continue
213				}
214				assertResultUntouched(t, rep.Results[j], saved[j],
215					"other duplicate entry changed after editing one")
216			}
217		}
218	}
