220	// TestReconcileDuplicateSameIDPaymentAndRefundStayIndependent 付款编号与退款编号
221	// 即使相同也仍是两类独立记录：同名重复组分别按付款、退款核对；编辑付款类结果的
222	// 记录编号/账户/金额/关联/位置，不能改变退款类各项，反之亦然。
223	func TestReconcileDuplicateSameIDPaymentAndRefundStayIndependent(t *testing.T) {
224		l := rangeLedger(t)
225		// 编号 "x1"：账本无付款 x1（重复组，无命中记录）；退款侧没有 x1 也无记录。
226		// 同时构造命中记录的同名编号：用 "r1" —— 付款 r1 账本无此付款（无记录），
227		// 退款 r1 命中 seq=1（重复两次）。这样同名编号横跨两类且一类带记录。
228		entries := []FlowEntry{
229			flowEntry(0, "payment", "r1", "aa-1", "usdc", 5, 0, 5, ""),
230			flowEntry(1, "payment", "r1", "aa-1", "usdc", 6, 0, 6, ""),
231			flowEntry(2, "refund", "r1", "aa-1", "usdc", 1000, 3, 1003, "p1"),
232			flowEntry(3, "refund", "r1", "aa-1", "usdc", 1000, 3, 1003, "p1"),
233		}
234		rep := mustReconcile(t, l, entries, reconBounds(0, 3, 0, 2))
235	
236		wantStatus := []string{ReconDuplicate, ReconDuplicate, ReconDuplicate, ReconDuplicate}
237		for i, s := range wantStatus {
238			if rep.Results[i].Status != s {
239				t.Fatalf("result %d status=%s want %s", i, rep.Results[i].Status, s)
240			}
241		}
242		// 付款 r1 在付款空间不存在 -> 无记录；退款 r1 命中 -> 带退款记录与原付款 p1。
243		for _, i := range []int{0, 1} {
244			if rep.Results[i].Record != nil {
245				t.Fatalf("payment r1 duplicate must have no record, result %d: %+v", i, rep.Results[i].Record)
246			}
247			if !reflect.DeepEqual(rep.Results[i].Positions, []int{0, 1}) {
248				t.Fatalf("payment r1 positions=%v want [0 1]", rep.Results[i].Positions)
249			}
250		}
251		wantRefundRec := ReconRecordRef{
252			Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
253			Amount: 1000, Fee: 3, Charged: 1003, Seq: 1, SettlementID: "p1",
254		}
255		for _, i := range []int{2, 3} {
256			if !reflect.DeepEqual(rep.Results[i].Positions, []int{2, 3}) {
257				t.Fatalf("refund r1 positions=%v want [2 3]", rep.Results[i].Positions)
258			}
259			if rep.Results[i].Record == nil {
260				t.Fatalf("refund r1 duplicate must carry record, result %d", i)
261			}
262			assertRefUntouched(t, *rep.Results[i].Record, wantRefundRec, "refund r1 record")
263		}
264	
265		saved := make([]ReconResult, len(rep.Results))
266		copy(saved, rep.Results)
267	
268		// 编辑付款类两条结果（含其空记录情形与位置列表）：退款类各项保持原值。
269		corruptReconResult(&rep.Results[0])
270		corruptReconResult(&rep.Results[1])
271		assertResultUntouched(t, rep.Results[2], saved[2], "refund entry changed by payment edits")
272		assertResultUntouched(t, rep.Results[3], saved[3], "refund entry changed by payment edits")
273	
274		// 再编辑退款类两条（含原付款关联 SettlementID）：已被改的付款项不再要求，
275		// 但退款类内部另一条在被改之前保持原值；且付款侧原本就无记录这一事实不变。
276		corruptReconResult(&rep.Results[2])
277		if rep.Results[3].Record == nil || rep.Results[3].Record.SettlementID != "p1" {
278			t.Fatalf("sibling refund result altered by editing one: %+v", rep.Results[3].Record)
279		}
280		corruptReconResult(&rep.Results[3])
281	}
