283	// ---- 2. 范围外优先：多条流水引用同一范围外记录，结果彼此独立并保留关联 ----
284	
285	// TestReconcileOutOfScopeResultsIndependentAndAssociationsKept 锁定记录在范围外时
286	// 优先报告 out_of_scope（优先于整组重复），各条都携带完整记录与跨范围关联；
287	// 同一范围外记录被多条流水引用时，编辑其中一条结果不能连带改变其他条目。
288	func TestReconcileOutOfScopeResultsIndependentAndAssociationsKept(t *testing.T) {
289		l := rangeLedger(t)
290		// 付款范围 (1,3]：p1(seq=1) 在范围外；p1 仍携带其退款 r1 的关联（不切断）。
291		// 退款范围 (1,2]：r1(seq=1) 在范围外，仍指向 p1。
292		entries := []FlowEntry{
293			flowEntry(0, "payment", "p1", "aa-1", "usdc", 1000, 3, 1003, ""),
294			flowEntry(1, "payment", "p1", "aa-1", "usdc", 999, 0, 999, ""), // 内容不同也优先 out_of_scope
295			flowEntry(2, "refund", "r1", "aa-1", "usdc", 1000, 3, 1003, "p1"),
296			flowEntry(3, "refund", "r1", "aa-1", "usdc", 1, 0, 1, "p-other"),
297		}
298		rep := mustReconcile(t, l, entries, reconBounds(1, 3, 1, 2))
299	
300		for i := range rep.Results {
301			if rep.Results[i].Status != ReconOutOfScope {
302				t.Fatalf("result %d status=%s want out_of_scope", i, rep.Results[i].Status)
303			}
304		}
305		wantPay := ReconRecordRef{
306			Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc",
307			Amount: 1000, Fee: 3, Charged: 1003, Seq: 1,
308			RefundID: "r1", RefundSeq: 1, // 范围外付款仍携带退款关联
309		}
310		wantRefund := ReconRecordRef{
311			Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
312			Amount: 1000, Fee: 3, Charged: 1003, Seq: 1, SettlementID: "p1", // 范围外退款仍指向原付款
313		}
314		assertRefUntouched(t, *rep.Results[0].Record, wantPay, "out-of-scope payment record")
315		assertRefUntouched(t, *rep.Results[1].Record, wantPay, "out-of-scope payment record")
316		assertRefUntouched(t, *rep.Results[2].Record, wantRefund, "out-of-scope refund record")
317		assertRefUntouched(t, *rep.Results[3].Record, wantRefund, "out-of-scope refund record")
318	
319		// out_of_scope 不附位置列表（只有 duplicate 才整组标位置），也不附差异。
320		for i := range rep.Results {
321			if rep.Results[i].Positions != nil {
322				t.Fatalf("out_of_scope result %d must not carry positions: %v", i, rep.Results[i].Positions)
323			}
324			if len(rep.Results[i].Diffs) != 0 {
325				t.Fatalf("out_of_scope result %d must not carry diffs: %+v", i, rep.Results[i].Diffs)
326			}
327		}
328		for i := 0; i < len(rep.Results); i++ {
329			for j := i + 1; j < len(rep.Results); j++ {
330				if rep.Results[i].Record == rep.Results[j].Record {
331					t.Fatalf("out_of_scope results %d and %d share one *ReconRecordRef", i, j)
332				}
333			}
334		}
335	
336		// 逐条引用同一范围外记录：编辑其中一条，其余条目（含另一类的同名编号）保持原值。
337		saved := make([]ReconResult, len(rep.Results))
338		copy(saved, rep.Results)
339		corrupted := map[int]bool{}
340		for i := range rep.Results {
341			corruptReconResult(&rep.Results[i])
342			corrupted[i] = true
343			for j := range rep.Results {
344				if corrupted[j] {
345					continue
346				}
347				assertResultUntouched(t, rep.Results[j], saved[j],
348					"other out_of_scope entry changed after editing one")
349			}
350		}
351	}
