353	// ---- 3. 报告改动与账本空间独立：账本、再对账都不沿用被改数据 ----
354	
355	// TestReconcileReportEditsDoNotReachLedger 调用者破坏性改写手里的整份报告
356	// （逐项详情、字段差异、缺失记录、金额与净额汇总），账本查询与用原流水原范围的
357	// 重新对账都必须仍依据真实账本计算，状态、关联、位置、汇总逐字段不变。
358	func TestReconcileReportEditsDoNotReachLedger(t *testing.T) {
359		l, path := reconLedger(t)
360	
361		// 构造覆盖全部状态的流水：matched、field_mismatch、missing_in_ledger、duplicate。
362		entries, err := ParseReconcileRequest([]byte(`{"entries":[
363		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003},
364		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":1,"charged":11},
365		  {"kind":"payment","id":"ghost","account":"aa-1","asset":"usdc","amount":5,"fee":0,"charged":5},
366		  {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"},
367		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":0,"charged":10}
368		]}`))
369		if err != nil {
370			t.Fatalf("parse: %v", err)
371		}
372		rep := mustReconcile(t, l, entries, ReconcileBounds{})
373		saved := cloneReconReport(rep) // 冻结：调用者取得时应得的完整报告
374	
375		// 账本查询基线。
376		snapBefore := mustQuery(t, l)
377	
378		// 破坏性改写整份报告：所有逐项结果（含记录与差异）、缺失记录、金额与净额汇总、
379		// 以及最大序号与范围字段。
380		for i := range rep.Results {
381			corruptReconResult(&rep.Results[i])
382		}
383		for i := range rep.MissingPayments {
384			corruptReconRef(&rep.MissingPayments[i])
385		}
386		for i := range rep.MissingRefunds {
387			corruptReconRef(&rep.MissingRefunds[i])
388		}
389		rep.MissingPayments = append(rep.MissingPayments, ReconRecordRef{ID: "fake-missing-pay"})
390		rep.MissingRefunds = append(rep.MissingRefunds, ReconRecordRef{ID: "fake-missing-ref"})
391		corruptReconTotals(rep.Totals.Ledger)
392		corruptReconTotals(rep.Totals.Flow)
393		for i := range rep.NetDiff {
394			rep.NetDiff[i].LedgerNetCharged = "1"
395			rep.NetDiff[i].FlowNetCharged = "2"
396			rep.NetDiff[i].NetChargedDiff = "999"
397		}
398		rep.NetDiff = append(rep.NetDiff, ReconNetDiff{Account: "zz", Asset: "gold", NetChargedDiff: "7"})
399		rep.MaxPaymentSeq = 4242
400		rep.MaxRefundSeq = 4242
401		rep.PaymentAfter = 4242
402		rep.PaymentThrough = 4242
403		rep.RefundAfter = 4242
404		rep.RefundThrough = 4242
405	
406		// 1. 账本余额与成功历史完全不变。
407		snapAfter := mustQuery(t, l)
408		if !reflect.DeepEqual(snapAfter, snapBefore) {
409			t.Fatalf("ledger changed by report edit:\nbefore=%+v\nafter =%+v", snapBefore, snapAfter)
410		}
411	
412		// 2. 用原流水与原范围重新对账：完整报告仍依据真实账本，逐字段等于冻结基线。
413		again := mustReconcile(t, l, entries, ReconcileBounds{})
414		assertReconReportDeepEqual(t, again, saved, "re-reconcile must not reuse caller edits")
415	
416		// 3. 报告改动不改变业务行为：已有付款编号重提仍 duplicate 携带真实原记录，
417		//    原付款仍只被原来的退款退回。
418		dup := mustSettle(t, l, 30, PaymentIntent{
419			ID: "p1", Account: "aa-1", Paymaster: "pm", Asset: "usdc",
420			Amount: i64p(1000), Nonce: 1, State: "pending",
421		})
422		if dup.Status != StatusDuplicate || dup.Record == nil ||
423			dup.Record.Charged != 1003 || dup.Record.Seq != 1 {
424			t.Fatalf("payment behavior changed by report edit: %+v", dup)
425		}
426		already := mustRefundOne(t, l, "r-again", "p1", "x")
427		if already.Status != StatusAlreadyRefunded {
428			t.Fatalf("refund behavior changed by report edit: %+v", already)
429		}
430	
431		// 4. 反复对账与编辑报告都不改写账本文件。
432		onDisk, err := os.ReadFile(path)
433		if err != nil {
434			t.Fatal(err)
435		}
436		if bytes.Contains(onDisk, []byte("HACK")) || bytes.Contains(onDisk, []byte("ghost")) ||
437			bytes.Contains(onDisk, []byte("4242")) {
438			t.Fatalf("reconcile/report edit leaked into the ledger file:\n%s", onDisk)
439		}
440	}
