442	// TestReconcileReportEditsDoNotReachRangedReconcile 在限定范围报告上重复空间独立：
443	// 编辑一份范围报告（含范围外记录与缺失）不能影响同范围或全量的再次对账。
444	func TestReconcileReportEditsDoNotReachRangedReconcile(t *testing.T) {
445		l := rangeLedger(t)
446		// 付款 (1,3]：p2、p3 入选，p1 范围外；退款 (0,1]：r1 入选，r2 范围外。
447		bounds := reconBounds(1, 3, 0, 1)
448		entries := []FlowEntry{
449			flowEntry(0, "payment", "p1", "aa-1", "usdc", 1000, 3, 1003, ""),  // out_of_scope
450			flowEntry(1, "payment", "p2", "aa-1", "usdc", 2000, 6, 2006, ""),  // matched
451			flowEntry(2, "refund", "r2", "aa-1", "usdc", 2000, 6, 2006, "p2"), // out_of_scope
452		}
453		rep := mustReconcile(t, l, entries, bounds)
454		saved := cloneReconReport(rep)
455	
456		// 先确认范围与关联符合预期，再整体破坏。
457		if rep.Results[0].Status != ReconOutOfScope || rep.Results[1].Status != ReconMatched ||
458			rep.Results[2].Status != ReconOutOfScope {
459			t.Fatalf("unexpected statuses: %s/%s/%s",
460				rep.Results[0].Status, rep.Results[1].Status, rep.Results[2].Status)
461		}
462		for i := range rep.Results {
463			corruptReconResult(&rep.Results[i])
464		}
465		for i := range rep.MissingPayments {
466			corruptReconRef(&rep.MissingPayments[i])
467		}
468		for i := range rep.MissingRefunds {
469			corruptReconRef(&rep.MissingRefunds[i])
470		}
471		corruptReconTotals(rep.Totals.Ledger)
472		corruptReconTotals(rep.Totals.Flow)
473	
474		// 同范围重新对账，逐字段恢复冻结基线（状态、跨范围关联、范围边界都来自真实账本）。
475		again := mustReconcile(t, l, entries, bounds)
476		assertReconReportDeepEqual(t, again, saved, "ranged re-reconcile must ignore edits")
477		if again.Results[0].Record == nil || again.Results[0].Record.RefundID != "r1" {
478			t.Fatalf("out-of-range payment must still link r1: %+v", again.Results[0].Record)
479		}
480		if again.Results[2].Record == nil || again.Results[2].Record.SettlementID != "p2" {
481			t.Fatalf("out-of-range refund must still link p2: %+v", again.Results[2].Record)
482		}
483		// 全量对账也不被范围报告的编辑污染。
484		full := mustReconcile(t, l, entries, ReconcileBounds{})
485		if full.Results[0].Status != ReconMatched || full.Results[2].Status != ReconMatched {
486			t.Fatalf("full reconcile tainted by ranged report edit: %s/%s",
487				full.Results[0].Status, full.Results[2].Status)
488		}
489	}
