491	// ---- 4. 时效独立：旧报告在账本后续付款/退款后仍冻结在取得时刻 ----
492	
493	// TestReconcileOldReportFreezesAcrossLaterPaymentAndRefund 取得报告后账本再发生
494	// 一笔付款与一笔退款：新报告反映真实变化；旧报告保留取得时的逐项结果、缺失列表、
495	// 金额汇总、最大成功序号与实际范围。尤其是原先未退款的付款后来被退款时，旧报告
496	// 里的付款不能自动出现新退款关联；新报告必须带上该关联，即使关联退款不在选定范围内。
497	func TestReconcileOldReportFreezesAcrossLaterPaymentAndRefund(t *testing.T) {
498		path := newTestLedger(t, []BalanceInit{
499			{Account: "aa", Asset: "usdc", Balance: 1_000_000},
500		})
501		l := openOrFail(t, path)
502	
503		// 初始只有一笔未退款的付款 p1。
504		if r := mustSettle(t, l, 0, intent("p1", "aa", "usdc", 100)); r.Status != StatusSettled {
505			t.Fatalf("settle p1: %+v", r)
506		}
507	
508		// 选定付款范围 (0,1]：只含 p1（显式固定，账本后续增长也不改变选定范围）；
509		// 退款范围为空 (0,0]，此时没有任何退款。
510		emptyRange := reconBounds(0, 1, 0, 0)
511		entries := []FlowEntry{
512			flowEntry(0, "payment", "p1", "aa", "usdc", 100, 0, 100, ""),
513		}
514		old := mustReconcile(t, l, entries, emptyRange)
515		if old.Results[0].Status != ReconMatched {
516			t.Fatalf("old report p1 status=%s", old.Results[0].Status)
517		}
518		if old.Results[0].Record == nil || old.Results[0].Record.RefundID != "" {
519			t.Fatalf("p1 must initially have no refund link: %+v", old.Results[0].Record)
520		}
521		if old.MaxPaymentSeq != 1 || old.MaxRefundSeq != 0 ||
522			old.PaymentAfter != 0 || old.PaymentThrough != 1 ||
523			old.RefundAfter != 0 || old.RefundThrough != 0 {
524			t.Fatalf("old report bounds/seqs: max=%d/%d bounds=%d,%d,%d,%d",
525				old.MaxPaymentSeq, old.MaxRefundSeq,
526				old.PaymentAfter, old.PaymentThrough, old.RefundAfter, old.RefundThrough)
527		}
528		oldSaved := cloneReconReport(old)
529	
530		// 账本再发生一笔新付款 p2（落在选定范围之外），随后退还原先未退款的 p1。
531		if r := mustSettle(t, l, 0, intent("p2", "aa", "usdc", 200)); r.Status != StatusSettled {
532			t.Fatalf("settle p2: %+v", r)
533		}
534		ref := mustRefundOne(t, l, "r1", "p1", "later refund")
535		if ref.Status != StatusRefundSuccess {
536			t.Fatalf("refund p1: %+v", ref)
537		}
538	
539		// 1. 旧报告完全冻结：p1 不自动出现新退款关联，缺失、汇总、max seq、范围都不变。
540		assertReconReportDeepEqual(t, old, oldSaved,
541			"old report must freeze across later payment/refund")
542		if old.Results[0].Record.RefundID != "" {
543			t.Fatalf("old report p1 acquired a refund link retroactively: %+v",
544				old.Results[0].Record)
545		}
546	
547		// 2. 用原流水、原范围重新对账：新报告反映真实变化。p1 现在带上退款关联 r1，
548		//    即使退款范围仍为空、r1 不在选定范围内（范围不切断关联）。
549		fresh := mustReconcile(t, l, entries, emptyRange)
550		if fresh.Results[0].Status != ReconMatched {
551			t.Fatalf("fresh p1 status=%s", fresh.Results[0].Status)
552		}
553		if fresh.Results[0].Record == nil ||
554			fresh.Results[0].Record.RefundID != "r1" || fresh.Results[0].Record.RefundSeq != 1 {
555			t.Fatalf("fresh report must carry the new refund link even if refund out of range: %+v",
556				fresh.Results[0].Record)
557		}
558		// 新报告的最大序号与范围反映新账本：付款 2、退款 1；选定范围仍是 (0,1]/(0,0]。
559		if fresh.MaxPaymentSeq != 2 || fresh.MaxRefundSeq != 1 {
560			t.Fatalf("fresh max seqs=%d/%d want 2/1", fresh.MaxPaymentSeq, fresh.MaxRefundSeq)
561		}
562		if fresh.PaymentThrough != 1 || fresh.RefundThrough != 0 {
563			t.Fatalf("fresh selected bounds changed: %d,%d", fresh.PaymentThrough, fresh.RefundThrough)
564		}
565		// p2 在选定付款范围之外；流水未引用它，但它属于真实账本（全量报告可见）。
566		full := mustReconcile(t, l, entries, ReconcileBounds{})
567		if full.MaxPaymentSeq != 2 || full.MaxRefundSeq != 1 {
568			t.Fatalf("full max seqs=%d/%d want 2/1", full.MaxPaymentSeq, full.MaxRefundSeq)
569		}
570		if full.Results[0].Record == nil || full.Results[0].Record.RefundID != "r1" {
571			t.Fatalf("full report p1 must link r1: %+v", full.Results[0].Record)
572		}
573	
574		// 3. 再次核对旧报告未受第二次对账影响。
575		assertReconReportDeepEqual(t, old, oldSaved, "old report changed after re-reconcile")
576	}
577	
578	// TestReconcileOldMissingReportFreezesAcrossLaterPayment 空流水正常返回的缺失报告
579	// 同样遵守时效独立：取得“全部缺失”报告后新增付款/退款，旧缺失报告仍保留取得时的
580	// 记录、关联、金额汇总、最大成功序号与范围；新报告只反映新账本。
581	func TestReconcileOldMissingReportFreezesAcrossLaterPayment(t *testing.T) {
582		path := newTestLedger(t, []BalanceInit{
583			{Account: "aa", Asset: "usdc", Balance: 1_000_000},
584		})
585		l := openOrFail(t, path)
586		if r := mustSettle(t, l, 0, intent("p1", "aa", "usdc", 100)); r.Status != StatusSettled {
587			t.Fatalf("settle p1: %+v", r)
588		}
589	
590		// 空流水：p1 列入缺失，且此时没有退款关联。
591		old := mustReconcile(t, l, nil, ReconcileBounds{})
592		if len(old.Results) != 0 {
593			t.Fatalf("empty flow must have no per-entry results: %+v", old.Results)
594		}
595		if len(old.MissingPayments) != 1 || old.MissingPayments[0].ID != "p1" {
596			t.Fatalf("old missing payments=%+v want [p1]", old.MissingPayments)
597		}
598		if old.MissingPayments[0].RefundID != "" {
599			t.Fatalf("p1 must initially have no refund link: %+v", old.MissingPayments[0])
600		}
601		if len(old.MissingRefunds) != 0 || old.MaxPaymentSeq != 1 || old.MaxRefundSeq != 0 {
602			t.Fatalf("old missing report seqs/counts: %+v", old)
603		}
604		oldSaved := cloneReconReport(old)
605	
606		// 账本再付款 p2 并退回 p1。
607		if r := mustSettle(t, l, 0, intent("p2", "aa", "usdc", 200)); r.Status != StatusSettled {
608			t.Fatalf("settle p2: %+v", r)
609		}
610		if r := mustRefundOne(t, l, "r1", "p1", "later"); r.Status != StatusRefundSuccess {
611			t.Fatalf("refund p1: %+v", r)
612		}
613	
614		// 旧缺失报告冻结：仍是仅 p1、无退款关联、max seq=1/0、汇总不变。
615		assertReconReportDeepEqual(t, old, oldSaved, "old missing report must freeze")
616		if old.MissingPayments[0].RefundID != "" {
617			t.Fatalf("old missing p1 acquired refund link retroactively: %+v",
618				old.MissingPayments[0])
619		}
620	
621		// 新缺失报告反映真实账本：p1 现带退款关联 r1；p2 仍缺失；r1 进入缺失退款。
622		fresh := mustReconcile(t, l, nil, ReconcileBounds{})
623		if ids := refs(fresh.MissingPayments); ids != "p1,p2" {
624			t.Fatalf("fresh missing payments=%s want p1,p2", ids)
625		}
626		if fresh.MissingPayments[0].RefundID != "r1" || fresh.MissingPayments[0].RefundSeq != 1 {
627			t.Fatalf("fresh missing p1 must link later refund r1: %+v", fresh.MissingPayments[0])
628		}
629		if ids := refs(fresh.MissingRefunds); ids != "r1" {
630			t.Fatalf("fresh missing refunds=%s want r1", ids)
631		}
632		if fresh.MaxPaymentSeq != 2 || fresh.MaxRefundSeq != 1 {
633			t.Fatalf("fresh max seqs=%d/%d want 2/1", fresh.MaxPaymentSeq, fresh.MaxRefundSeq)
634		}
635	
636		// 编辑旧报告同样不能污染这份新报告：再取一次仍与 fresh 一致。
637		corruptReconRef(&old.MissingPayments[0])
638		again := mustReconcile(t, l, nil, ReconcileBounds{})
639		assertReconReportDeepEqual(t, again, fresh, "new report tainted by editing old report")
640	}
641	
642	// ---- 5. 只读：对账本身不改写账本文件 ----
643	
644	// TestReconcileRangedAndEditsDoNotRewriteLedgerFile 在限定范围对账上锁定只读：
645	// 仅对账（含范围外命中与缺失）以及编辑返回报告，账本文件字节保持不变。
646	func TestReconcileRangedAndEditsDoNotRewriteLedgerFile(t *testing.T) {
647		l := rangeLedger(t)
648		path := l.path
649		bounds := reconBounds(1, 2, 0, 1)
650		entries := []FlowEntry{
651			flowEntry(0, "payment", "p1", "aa-1", "usdc", 1000, 3, 1003, ""), // 范围外
652			flowEntry(1, "refund", "r2", "aa-1", "usdc", 2000, 6, 2006, "p2"),
653		}
654	
655		before, err := os.ReadFile(path)
656		if err != nil {
657			t.Fatal(err)
658		}
659		for i := 0; i < 3; i++ {
660			rep := mustReconcile(t, l, entries, bounds)
661			for j := range rep.Results {
662				corruptReconResult(&rep.Results[j])
663			}
664			for j := range rep.MissingPayments {
665				corruptReconRef(&rep.MissingPayments[j])
666			}
667			corruptReconTotals(rep.Totals.Ledger)
668			corruptReconTotals(rep.Totals.Flow)
669			if _, err := json.Marshal(rep); err != nil {
670				t.Fatal(err)
671			}
672		}
673		after, err := os.ReadFile(path)
674		if err != nil {
675			t.Fatal(err)
676		}
677		if !bytes.Equal(before, after) {
678			t.Fatalf("ledger file rewritten by ranged reconcile/edits:\nbefore=%s\nafter =%s",
679				before, after)
680		}
681	
682		// 已有付款与退款记录数量不变，余额仍可正常支持后续付款（对账未扣加余额）。
683		snap := mustQuery(t, l)
684		if len(snap.Settlements) != 3 || len(snap.Refunds) != 2 {
685			t.Fatalf("history counts changed: settlements=%d refunds=%d",
686				len(snap.Settlements), len(snap.Refunds))
687		}
688		if r := mustSettle(t, l, 0, intent("p9", "aa-1", "usdc", 100)); r.Status != StatusSettled {
689			t.Fatalf("payment after reconciles must behave normally: %+v", r)
690		}
691		if r := mustRefundOne(t, l, "r9", "p9", "x"); r.Status != StatusRefundSuccess {
692			t.Fatalf("refund after reconciles must behave normally: %+v", r)
693		}
694	}
695

